style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://i.imgur.com/gvUfbC5.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: white !important;
  }

  .content,
  .section,
  .container-main,
  .game-home-page,
  .nav-container,
  .rbx-header,
  .footer-container,
  .navbar,
  .game-card-container,
  .game-card,
  .text,
  .game-card-name,
  .container-footer,
  .rbx-tabs-horizontal,
  .dropdown-menu,
  .modal-content,
  .rbx-left-col,
  .rbx-right-col,
  .rbx-main-content {
    background-color: rgba(0, 0, 0, 0.85) !important;
    color: white !important;
    border: 1px solid #000 !important;
  }

  a,
  span,
  p,
  h1, h2, h3, h4, h5, h6,
  .text-label,
  .text-overflow {
    color: white !important;
  }

  /* Optional: Remove weird gray hover colors */
  .game-card:hover {
    background-color: rgba(255, 255, 255, 0.1) !important;
  }
}
